/* From Uiverse.io by mi-series - Tags: simple, form, survey form, feedback, survey */
.__UIV_SCOPE__ form, .__UIV_SCOPE__ p {
  padding: 0;
  margin: 0;
  outline: none;
  font-family: Roboto, Arial, sans-serif;
  font-size: 14px;
  color: #000;
  line-height: 13px;
  border-radius: 10px;
}

.__UIV_SCOPE__ #h1 {
  font-size: 24px;
  font-weight: 400;
  text-align: center;
}

.__UIV_SCOPE__ #h4 {
  margin: 20px 0 2px;
  color: #000;
}

.__UIV_SCOPE__ .testbox {
  display: flex;
  justify-content: center;
  align-items: center;
  height: inherit;
  padding: 80px;
}

.__UIV_SCOPE__ form {
  width: 100%;
  padding: 20px;
  background: #EBEBE1;
  box-shadow: 0 2px 5px #ccc;
}

.__UIV_SCOPE__ .input {
  width: calc(100% - 10px);
  padding: 5px;
  border: 1px solid #000;
  border-radius: 3px;
  vertical-align: middle;
  background-color: #F7F7F7;
}

.__UIV_SCOPE__ .input:hover, .__UIV_SCOPE__ textarea:hover {
  outline: none;
  border: 1px solid #000;
}

.__UIV_SCOPE__ .first-name {
  margin-bottom: 5px;
}

.__UIV_SCOPE__ th, .__UIV_SCOPE__ td {
  width: 21%;
  padding: 15px 0;
  border-bottom: 1px solid #ccc;
  text-align: center;
  vertical-align: set;
  line-height: 18px;
  font-weight: 400;
  word-break: break-all;
}

.__UIV_SCOPE__ .first-col {
  width: 16%;
  text-align: left;
}

.__UIV_SCOPE__ table {
  width: 100%;
}

.__UIV_SCOPE__ textarea {
  width: calc(100% - 6px);
  background: #F7F7F7;
  border-radius: 5px;
}

.__UIV_SCOPE__ .btn-block {
  margin-top: 20px;
  text-align: center;
}

.__UIV_SCOPE__ button {
  width: 150px;
  padding: 10px;
  border: none;
  -webkit-border-radius: 5px;
  -moz-border-radius: 5px;
  border-radius: 5px;
  background-color: #F3D153;
  font-size: 16px;
  color: #000;
  cursor: pointer;
}

.__UIV_SCOPE__ button:hover {
  opacity: .9;
}

@media (min-width: 568px) {
  .__UIV_SCOPE__ th, .__UIV_SCOPE__ td {
    word-break: keep-all;
  }
}
